from fastapi import FastAPI
from fastapi.testclient import TestClient

def s_start():
    print("SYNC START", flush=True)

def s_stop():
    print("SYNC STOP", flush=True)

app = FastAPI(on_startup=[s_start], on_shutdown=[s_stop])

@app.get("/health")
async def health():
    return {"ok": True}

def test_startup_shutdown():
    with TestClient(app) as client:
        client.get("/health")

if __name__ == "__main__":
    test_startup_shutdown()
EOF
